export type WaveformChunk = {
  /** Interleaved unsigned 16-bit peak / RMS measurements, generated by FFmpeg. */
  values: Uint16Array
  sampleHz: number
}

export type WaveformData = {
  duration: number
  chunkSeconds: number
  chunks: Map<number, WaveformChunk>
  revision: number
  requestRange: (start: number, end: number, consumer: string) => void
}
